            // Add estimated time left if enabled
            if (configStore.getValue(Constants.DISPLAY_TIME_LEFT) && plugin.isFightInProgress()) {
                long timeLeftMillis = plugin.getEstimatedTimeRemainingMillis();
                if (timeLeftMillis > 0) {
